problem_statement:
Dynamic-import checker reports a lazy import as defeated by an `import type`

`findIneffectiveDynamicImports` (scripts/lib/dynamic-imports.mjs) flags a dynamic `import()` as ineffective when some other module in the graph imports the same module statically. It currently counts type-only statements as static imports.

Real case: `use-link-palette.ts` reads a type from `markdown-editor` with `import type { ... } from "./markdown-editor"`, which TypeScript erases entirely, yet `post-editor.tsx`'s lazy `import()` of `markdown-editor` is reported as ineffective even though the chunk does split.

Reproduce:
```js
findIneffectiveDynamicImports([
  { path: "app/a.ts", source: 'import type { LinkTarget } from "./editor";
export type * from "./editor";' },
  { path: "app/b.tsx", source: 'const E = lazy(() => import("./editor"));' },
]);
```
returns one finding; it should return `[]`.

Expected: a whole statement the build erases (`import type ... from`, `export type ... from`) defeats nothing. Do not over-correct, though:
- a braced list in which every specifier is `type X` (e.g. `import { type A, type B } from "./editor"`) is NOT erased under this repo's `verbatimModuleSyntax` (it is kept as a side-effect import) and must still count;
- a mixed list such as `import { type A, b }` still counts;
- `import type from "./editor"` is a default import named `type` and still counts.

gold_patch:
diff --git a/scripts/lib/dynamic-imports.mjs b/scripts/lib/dynamic-imports.mjs
index 6aa2952b..59b163fa 100644
--- a/scripts/lib/dynamic-imports.mjs
+++ b/scripts/lib/dynamic-imports.mjs
@@ -20,6 +20,20 @@ export function moduleKey(spec, from) {
   return path.replace(/\.(?:ts|tsx|mjs|js)$/, "").replace(/\/index$/, "");
 }

+/**
+ * True when the build erases the whole statement: `import type { X }`, `export type * from`. A
+ * braced list whose every specifier is `type X` is NOT erased: under this repo's
+ * verbatimModuleSyntax the oxc transform Vite runs keeps it as the side-effect import
+ * `import "x"` (measured 2026-09-25 with rolldown/utils transformSync), which still loads the
+ * module statically. `import type from "x"` is a default import named `type`.
+ *
+ * @param {string} clause the text between `import`/`export` and `from`
+ */
+function isTypeOnlyClause(clause) {
+  // Trimmed, so a bare `type` (the default import named type) has nothing after it and fails.
+  return /^type(?:\s+[\w${*]|\s*[{*])/.test(clause.trim());
+}
+
 /**
  * A dynamic import splits nothing when some module in the same graph imports it statically.
  * Files are `{ path, source }` with repo-relative paths.
@@ -34,8 +48,13 @@ export function findIneffectiveDynamicImports(files) {

   for (const { path, source } of files) {
     const code = stripComments(source);
-    for (const m of code.matchAll(/\bfrom\s*["']([^"']+)["']/g)) {
-      const key = moduleKey(m[1], path);
+    // The clause is everything between the nearest `import`/`export` and `from`, so a statement
+    // before it on an unterminated line cannot lend it a type-only reading or take one away.
+    for (const m of code.matchAll(
+      /\b(?:import|export)\s+((?:(?!\b(?:import|export)\b)[^;"'`])*?)\bfrom\s*["']([^"']+)["']/g,
+    )) {
+      if (isTypeOnlyClause(m[1])) continue;
+      const key = moduleKey(m[2], path);
       if (!key) continue;
       if (!statics.has(key)) statics.set(key, []);
       /** @type {string[]} */ (statics.get(key)).push(path);
